1	// How a scenario unfolds. This module knows the order events happen in and
2	// what each step leaves behind for the next one; it delegates what a policy
3	// costs to pricing.ts and what it pays out to coverage.ts.
4	
5	import { premiumFor, type Customer, type Item } from "./pricing.js";
6	import { capFor, payoutForDamages, type Damage } from "./coverage.js";
7	
8	export type { Customer, KnownItemType } from "./pricing.js";
9	export type { Damage } from "./coverage.js";
10	
11	export interface Scenario {
12	  customer: Customer;
13	  steps: Step[];
14	}
15	
16	export interface QuoteStep {
17	  op: "quote";
18	  items: Item[];
19	}
20	
21	export interface ClaimStep {
22	  op: "claim";
23	  policy: number;
24	  incident: { cause: string; damages: Damage[] };
25	}
26	
27	export type Step = QuoteStep | ClaimStep;
28	
29	export interface ScenarioResults {
30	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
31	}
32	
33	// What earlier steps have established by the time a later step is priced.
34	// Steps are not independent: a quote is a follow-up contract when the customer
35	// already took a quote earlier in the same scenario. Folding this forward —
36	// rather than re-deriving it from the step prefix — is what lets a step read
37	// the state its predecessors left behind.
38	interface Policy {
39	  // The insured items, kept because a claim is settled against them: what a
40	  // damage reimburses depends on the item's own material and enchantment, not
41	  // on the damage entry alone.
42	  items: Item[];
43	  remainingCap: number;
44	}
45	
46	interface ScenarioState {
47	  hasQuoted: boolean;
48	  // Keyed by the step index of the quote that created the policy, which is
49	  // how a later claim step refers to it.
50	  policies: Map<number, Policy>;
51	}
52	
53	const INITIAL_STATE: ScenarioState = { hasQuoted: false, policies: new Map() };
54	
55	type StepOutcome = ScenarioResults["results"][number];
56	
57	interface StepRun {
58	  outcome: StepOutcome;
59	  state: ScenarioState;
60	}
61	
62	// Every policy a step establishes is recorded the same way, so both handlers
63	// go through here rather than each rebuilding the map.
64	const withPolicy = (
65	  state: ScenarioState,
66	  index: number,
67	  policy: Policy,
68	): ScenarioState => ({
69	  ...state,
70	  policies: new Map(state.policies).set(index, policy),
71	});
72	
73	const runQuote = (
74	  { items }: QuoteStep,
75	  customer: Customer,
76	  state: ScenarioState,
77	  index: number,
78	): StepRun => ({
79	  outcome: {
80	    premium: premiumFor(items, {
81	      customer,
82	      isFollowUpContract: state.hasQuoted,
83	    }),
84	  },
85	  state: withPolicy({ ...state, hasQuoted: true }, index, {
86	    items,
87	    remainingCap: capFor(items),
88	  }),
89	});
90	
91	const runClaim = (
92	  { policy: policyIndex, incident }: ClaimStep,
93	  state: ScenarioState,
94	): StepRun => {
95	  // A claim always names a policy an earlier quote step created. Nothing
96	  // validates that yet — the test rejecting unknown references will force the
97	  // question of what to do when it is absent.
98	  const policy = state.policies.get(policyIndex) ?? {
99	    items: [],
100	    remainingCap: 0,
101	  };
102	  const payout = payoutForDamages(policy.items, incident.damages);
103	  const remainingCap = policy.remainingCap - payout;
104	
105	  return {
106	    outcome: { payout, remainingCap },
107	    state: withPolicy(state, policyIndex, { ...policy, remainingCap }),
108	  };
109	};
110	
111	// Dispatches a step to its handler. Written as an exhaustive switch on `op`
112	// so that adding a step kind to the Step union turns "I forgot to handle it"
113	// into a compile error rather than a wrong number.
114	const runStep = (
115	  step: Step,
116	  customer: Customer,
117	  state: ScenarioState,
118	  index: number,
119	): StepRun => {
120	  switch (step.op) {
121	    case "quote":
122	      return runQuote(step, customer, state, index);
123	    case "claim":
124	      return runClaim(step, state);
125	  }
126	};
127	
128	export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
129	  const { results } = steps.reduce<{
130	    results: StepOutcome[];
131	    state: ScenarioState;
132	  }>(
133	    ({ results, state }, step, index) => {
134	      const stepRun = runStep(step, customer, state, index);
135	      return { results: [...results, stepRun.outcome], state: stepRun.state };
136	    },
137	    { results: [], state: INITIAL_STATE },
138	  );
139	
140	  return { results };
141	};
